"""Contenu des guides de boss (onglet Donjons) — curé à l'avance à partir de
dofuspourlesnoobs.com et de captures fournies par l'utilisateur, donc statique
ici plutôt que dans settings.json (qui est local/gitignored, jamais
présent sur une install fraîche). Les images qu'il référence (guide_*.png,
etat_*.png, mob_*.png...) vivent dans skin/, bundlée par PyInstaller."""

DEFAULT_GUIDES = {
    'harrebourg': '<h3 style="color:#ff8a1e; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">État vulnérabilité</h3><p style="margin:0 0 10px 0; line-height:1.55;">Une icône au-dessus du Comte indique le mode actif : <b style="color:#5fb3e0;">bleue</b> (tour impair) → <u>c\'est VOUS</u> qui êtes téléporté symétriquement par rapport à lui quand vous le tapez. <b style="color:#3fb950;">verte/engrenage</b> (tour pair) → <u>c\'est LUI</u> qui est téléporté symétriquement par rapport à vous.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#ff8a1e;">Pour le rendre vulnérable</b> : provoquer un échange de place (sort d\'échange, allié ou ennemi) au moment précis où le Comte change de position.</p><p style="margin:4px 0 12px 0;"><a href="zoom:guide_etat.png"><img src="guide_etat.png" width="420" height="188"></a></p><h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Confusion — où taper</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#e05555;">À chaque début de votre tour</b>, vos sorts partent redirigés selon les PV du Comte — vérifier la tranche ci-dessous et viser la case indiquée AVANT de lancer.</p><p style="margin:4px 0 12px 0;"><a href="zoom:guide_indications.png"><img src="guide_indications.png" width="420" height="443"></a></p><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Sorts clés</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b>Mi-temps</b> (début de tour du Comte) : glyphe croix taille 3 autour de lui — <u>mort instantanée</u> si un allié commence son tour dedans.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Contretemps</b> : 700 dégâts Terre + dégâts Eau (selon PV manquants). Si le Comte est vulnérable, téléporte la cible à sa position de début de tour.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Jaquemart</b> (phase invulnérable, jusqu\'à 4PO) : 700 dégâts Eau + vol de vie + retire 3-4 PA.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Multicomte</b> (phase vulnérable) : 500 dégâts Feu en cercle rayon 3-5 + invoque des illusions/clones.</p><p style="color:#9ca3af; font-size:10.5px; margin-top:4px;">PV totaux non précisés par la source — 5 PM, IA "Agressive".</p>',
    'vortex': '<h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Priorité absolue</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#e05555;"><u>Le tuer le plus TÔT possible</u></b> dans le cycle de l\'Auroraire — chaque heure ajoute un boost cumulatif aux monstres corrompus. Traîner jusqu\'à 10-12h le rend <u>quasi injouable</u> (10h Inébranlable, 11h +30% Vitalité, 12h +400 Agilité).</p><h3 style="color:#ff8a1e; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Rendre vulnérable</h3><p style="margin:0 0 10px 0; line-height:1.55;">Vortex démarre invulnérable, indéplaçable, 0 PM. Corrompre les 5 vagues en tuant <b>chaque monstre 2 FOIS À LA MÊME HEURE</b> de l\'Auroraire (avance d\'1h par tour de perso). +2 tours après corruption totale avant qu\'il devienne vulnérable.</p><h3 style="color:#3fb950; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">À quelle heure tuer les mobs</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#3fb950;">TUER à ces heures</b> : 2h · 3h · 4h · 6h · 8h · 9h · 12h.<br><b style="color:#e05555;">NE JAMAIS tuer à ces heures</b> : 1h · 5h · 7h · 10h · 11h.</p><h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Lignes de l\'Auroraire — où il tape</h3><p style="margin:0 0 10px 0; line-height:1.55;">Sort <b>« En temps et en heure »</b> : le Vortex tape tout ce qui est aligné avec l\'Auroraire sur la ligne correspondant à l\'heure actuelle (schéma ci-dessous, 1 à 12).</p><p style="margin:4px 0 12px 0;"><a href="zoom:guide_schema.png"><img src="guide_schema.png" width="420" height="151"></a></p><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#3fb950;">Astuce réduction de risque</b> : en équipe de taille <u>diviseur de 12</u> (2, 3, 4 ou 6), le cycle de l\'Auroraire se répète toujours pareil — certaines lignes ne sont alors jamais atteintes pendant le tour du Vortex.</p><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Boosts par heure (monstres corrompus)</h3><p style="margin:0 0 10px 0; line-height:1.55;"><span style="color:#3fb950;">■</span> heure conseillée pour tuer &nbsp; <span style="color:#e05555;">■</span> heure à éviter</p><table style="width:100%; border-collapse:collapse; font-size:11.5px; margin-bottom:6px;"><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">I</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="cc.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+10% critique&nbsp;&nbsp;<img src="docrit.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+200 dégâts critiques</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#e05555; font-weight:700; font-size:10.5px;">ÉVITER</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">II</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="etat_generique.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">État Intaclable</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">III</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="in.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+400 Intelligence</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">IV</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="pm.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+2 PM</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">V</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="dmgRecus.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">Dégâts subis x70%</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#e05555; font-weight:700; font-size:10.5px;">ÉVITER</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">VI</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="ch.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+400 Chance</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">VII</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="rcc.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+150 résistances critique</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#e05555; font-weight:700; font-size:10.5px;">ÉVITER</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">VIII</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="pa.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+4 PA</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">IX</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="fo.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+400 Force</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">X</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="etat_inebranlable.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">État Inébranlable</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#e05555; font-weight:700; font-size:10.5px;">ÉVITER</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">XI</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="pv.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+30% Vitalité</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#e05555; font-weight:700; font-size:10.5px;">ÉVITER</span></td></tr><tr><td style="padding:5px 8px 5px 0; vertical-align:middle;"><span style="display:inline-block; width:22px; height:22px; line-height:22px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:11px; font-weight:700;">XII</span></td><td style="padding:5px 6px 5px 0; vertical-align:middle;"><img src="ag.png" width="14" height="14" style="vertical-align:-3px; margin-right:3px;">+400 Agilité</td><td style="padding:5px 0; white-space:nowrap; vertical-align:middle;"><span style="color:#3fb950; font-weight:700; font-size:10.5px;">TUER ICI</span></td></tr></table><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Sorts clés</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b>Heurage</b> : téléporte le Vortex au contact de l\'Auroraire (tous les 3 tours).</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Heuristique</b> (jusqu\'à 8PO) : 1200 dégâts Air/Feu, réduit les envoûtements de 2 tours, applique <img src="etat_pacifiste.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;">Pacifiste.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Morfaille</b> (jusqu\'à 4PO) : 20% des PV érodés en dégâts Terre, poison qui refait le sort au tour suivant.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>En temps et en heure</b> (sans PM) : 800 dégâts Terre + 50% des PV érodés + 20% érosion sur les alignés avec l\'Auroraire.</p>',
    'rdv': '<h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Priorité absolue</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#e05555;"><u>Tuer la Reine dès que possible</u></b> — à sa mort, <b style="color:#e05555;">Péché Mignon</b> inflige <b>+50% de dégâts subis pour le reste du combat</b>. Mieux vaut l\'achever vite malgré ce malus que la laisser s\'accumuler des tours en plus.</p><p style="margin:0 0 10px 0; line-height:1.55;">Mécanique clé : <b style="color:#ff8a1e;">-10% de dégâts subis PAR Bombe présente sur le terrain</b> — plus il y a de Bombes vivantes, plus elle est résistante. <u>Gérer/limiter les Bombes en priorité</u>.</p><h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Priorité des cibles</h3><ul style="margin:0 0 10px 0; padding-left:18px;"><li style="margin-bottom:5px;"><img src="mob_magouille.png" width="18" height="18" style="vertical-align:-4px; margin-right:4px;"><b style="color:#c8a000;">Magouilles</b> : retirez-leur de la <b>PO</b>.</li><li style="margin-bottom:5px;"><img src="mob_terristocrate.png" width="18" height="18" style="vertical-align:-4px; margin-right:4px;"><b style="color:#c8a000;">Terristocrates</b> : retirez-leur des <b>PM</b>.</li><li style="margin-bottom:5px;"><img src="boss_rdv.png" width="18" height="18" style="vertical-align:-4px; margin-right:4px;"><b style="color:#e05555;">Reine des Voleurs</b> : à tuer rapidement (cf. ci-dessus).</li></ul><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Gestion des Bonbombes</h3><p style="margin:0 0 10px 0; line-height:1.55;">Chaque tour, votre perso invoque automatiquement une Bonbombe à 2PO devant lui (sens horaire si la case est occupée). <b>2 Bonbombes invoquées par le même perso</b> → la 1ère explose, fait exploser en chaîne celles en ligne avec elle (la plus proche explose ensuite, etc.).</p><ul style="margin:0 0 10px 0; padding-left:18px;"><li style="margin-bottom:5px;"><b style="color:#e05555;">Rouge</b> (couleur de base) : à l\'explosion, <b style="color:#e05555;">OS tous les persos/invocations en ligne à 10PO</b> + ~1200 dégâts Feu aux ennemis dans la même zone.</li><li style="margin-bottom:5px;"><b style="color:#5fb3e0;">Bleue</b> (devient bleue si une AUTRE bombe explose en diagonale d\'elle) : <b style="color:#3fb950;">soigne intégralement vos persos en ligne à 10PO</b> + ~1200 dégâts Feu aux monstres dans la même zone — inoffensive pour vous, mais toujours dangereuse pour les monstres.</li><li style="margin-bottom:5px;">Invulnérables, <u>poussables mais pas portables/jetables</u> (<img src="etat_lourd.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;">état Lourd). <u>La Reine est immunisée aux dégâts des Bonbombes</u>.</li></ul><p style="margin:4px 0 12px 0;"><a href="zoom:guide_bombes_chaine.png"><img src="guide_bombes_chaine.png" width="420" height="309"></a></p><h3 style="color:#3fb950; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Placement anti-bombe recommandé</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#3fb950;">Si vous gérez mal les Bombes, utilisez ce placement</b> : vos persos en diagonale les uns des autres, <u>le plus d\'initiative en haut</u>. Chacun invoque sa bombe dans sa propre diagonale (case déjà occupée par l\'allié précédent) — les bombes explosent toujours en chaîne <u>sans jamais toucher vos persos</u>, la dernière devient bleue et soigne. Seul risque : ça peut bloquer vos déplacements vers la droite.</p><p style="margin:4px 0 12px 0;"><a href="zoom:guide_placement_sur.png"><img src="guide_placement_sur.png" width="420" height="329"></a></p><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Sorts clés</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b>Coup Critique</b> (2x/tour, mêlée) : ~900 dégâts Eau (~1500 tous éléments en critique) + poison selon PM utilisés. En critique, réduit la durée des effets de la cible de 4 tours.</p><p style="margin:0 0 10px 0; line-height:1.55;"><img src="etat_mort_en_sursis.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;"><b>Mort en Sursis</b> (2x/tour, ligne jusqu\'à 5 cases) : s\'attire sur la cible puis échange de position. Applique un état mortel — <u>mort en 6 tours sans soin des Bonbombes</u>.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Brume</b> (à partir du tour 4, relance 3 tours) : en fin de tour, pose un glyphe noir rayon 3 et devient invisible dedans. <u>Ne peut occuper que 3 cases précises (33% chacune)</u> — positionnement prévisible à exploiter (schéma ci-dessous).</p><p style="margin:4px 0 12px 0;"><a href="zoom:guide_brume.png"><img src="guide_brume.png" width="420" height="198"></a></p><h3 style="color:#3fb950; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Stratégie</h3><p style="margin:0 0 10px 0; line-height:1.55;">Rester à distance pour éviter Mort en Sursis. Anticiper les 3 cases possibles de la Brume. Limiter le nombre de Bombes en vie pour garder les dégâts efficaces.</p>',
    'koutoulou': '<h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Priorité des cibles</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#e05555;">Focus en priorité</b> : <img src="mob_klutiste.png" width="18" height="18" style="vertical-align:-5px; margin-right:5px;"><b style="color:#c8a000;">Klûtiste</b> et <img src="mob_lifo.png" width="18" height="18" style="vertical-align:-5px; margin-right:5px;"><b style="color:#c8a000;">Li-Fo</b>.</p><p style="margin:0 0 10px 0; line-height:1.5; padding:8px 10px; border-left:3px solid #e05555; background:rgba(255,255,255,0.03); border-radius:4px;">À partir du tour 2, le <b>Li-Fo</b> peut <u>invoquer une copie d\'un monstre de la salle (hors Koutoulou) à 3PO ou moins</u> de lui. <b style="color:#e05555;">Éviter absolument qu\'il dédouble le Klûtiste</b>.</p><h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Piège principal : ligne de vue</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b>Vacillement de l\'univers</b> : <u>terminer son tour en ligne de vue du Koutoulou</u> fait gagner un état de Folie.</p><p style="margin:0 0 10px 0; line-height:1.5; padding:8px 10px; border-left:3px solid #e05555; background:rgba(255,255,255,0.03); border-radius:4px;"><b style="color:#e05555;">SUPER IMPORTANT</b> : à partir du tour 2, à <u>chaque début de tour du Koutoulou</u>, il téléporte TOUS les persos dans sa ligne de vue à son contact. <img src="etat_pesanteur.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;"><b style="color:#3fb950;">Pesanteur</b>, <img src="etat_indeplacable.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;"><b style="color:#3fb950;">Indéplaçable</b> ou <img src="etat_enracine.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;"><b style="color:#3fb950;">Enraciné</b> <b style="color:#3fb950;">bloquent CETTE téléportation</b> (contrairement à l\'échange forcé ci-dessous).</p><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#3fb950;">Astuce</b> : <u>placer une invocation devant le Koutoulou en fin de tour</u> pour lui bloquer la ligne de vue.</p><h3 style="color:#e05555; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Horreur Cosmique — échanges de place forcés</h3><p style="margin:0 0 10px 0; line-height:1.55;">Échanger de place <b>2 fois avec le même ENNEMI</b> pendant votre tour → cet ennemi devient <img src="etat_invulnerable.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;"><b>invulnérable jusqu\'au prochain tour de l\'allié qui l\'a rendu invulnérable</b> + vous gagnez un état de <b style="color:#e05555;">Folie (cumulable)</b>.</p><p style="margin:0 0 10px 0; line-height:1.55;">Échanger de place <b>2 fois avec le même ALLIÉ</b> pendant votre tour → vous gagnez un état de <b style="color:#e05555;">Folie (cumulable)</b>.</p><p style="margin:0 0 10px 0; line-height:1.55;">Décrémente de 1 au début de chaque tour du perso — cf. détail des niveaux plus bas.</p><p style="margin:0 0 10px 0; line-height:1.5; padding:8px 10px; border-left:3px solid #e05555; background:rgba(255,255,255,0.03); border-radius:4px;"><b style="color:#e05555;">NOTE IMPORTANTE</b> : cet échange est un <b style="color:#e05555;">déplacement FORCÉ</b> — <u>il N\'EST PAS bloqué par <img src="etat_pesanteur.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;">Pesanteur, <img src="etat_enracine.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;">Enraciné ou <img src="etat_indeplacable.png" width="16" height="16" style="vertical-align:-4px; margin:0 2px;">Indéplaçable</u>, contrairement à la règle générale (cf. bouton « États de déplacement » en haut de la page).</p><p style="margin:0 0 10px 0; line-height:1.55;"><b style="color:#3fb950;">Contournement</b> : <u>privilégier les poisons</u> (dégâts indirects, ne déclenchent PAS d\'échange de place) plutôt que les dégâts directs quand c\'est possible.</p><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Niveaux de Folie</h3><p style="margin:0 0 10px 0; line-height:1.55;">États de Folie 1 à 10 (affiché au-dessus du personnage) — certains niveaux précis apportent un malus :</p><ul style="margin:0 0 10px 0; padding-left:18px;"><li style="margin-bottom:5px;"><span style="display:inline-block; width:20px; height:20px; line-height:20px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:10px; font-weight:700; margin-right:6px;">II</span><b>Folie 2</b> : inflige 100% des dégâts du sort utilisé à tous les alliés en zone 2PO autour de vous.</li><li style="margin-bottom:5px;"><span style="display:inline-block; width:20px; height:20px; line-height:20px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:10px; font-weight:700; margin-right:6px;">IV</span><b>Folie 4</b> : soins reçus x50%.</li><li style="margin-bottom:5px;"><span style="display:inline-block; width:20px; height:20px; line-height:20px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:10px; font-weight:700; margin-right:6px;">VI</span><b>Folie 6</b> : dégâts subis x100%.</li><li style="margin-bottom:5px;"><span style="display:inline-block; width:20px; height:20px; line-height:20px; text-align:center; border-radius:50%; background:#4a5060; color:#ffffff; font-size:10px; font-weight:700; margin-right:6px;">X</span><b style="color:#e05555;">Folie 10</b> : <b style="color:#e05555;">mort, OS</b>.</li></ul><h3 style="color:#c8a000; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Sorts clés</h3><p style="margin:0 0 10px 0; line-height:1.55;"><b>Frappe Koutonienne</b> (4x/tour, 2x/cible, mêlée uniquement) : 1300 dégâts Terre + état de Folie.</p><p style="margin:0 0 10px 0; line-height:1.55;"><b>Permutation Inquiétante</b> (dès le tour 2, 2x/tour, 1x/cible, jusqu\'à 6PO, sans ligne de vue) : échange de place avec un allié.</p><h3 style="color:#3fb950; font-size:13px; margin:0 0 6px 0; letter-spacing:.3px;">Stratégie</h3><p style="margin:0 0 10px 0; line-height:1.55;">Terminer les tours à plus de 6PM du boss ou hors ligne de vue (invocation-bouclier). Éliminer les alliés dangereux (cf. Priorité des cibles) et le Shokkoth — une fois Koutoulou seul, le combat devient très gérable. Éviter les doubles du Shokkoth en restant à distance.</p>',
}
